public Order Submit(Order? order)
{
    ArgumentNullException.ThrowIfNull(order);            // guard: bad input
    if (order.Lines.Count == 0)
        throw new ArgumentException("empty order", nameof(order));
    if (_clock.Now < order.ReadyAt)
        return order with { Status = Status.Pending };   // guard: not ready yet
    return _processor.Run(order);                        // happy path stays flat
}
